                centers.append((r,c,color))
    for r,c,color in centers:
        for x in range(w):
            if grid[r][x]==0: out[r][x]=color
    for r,c,color in centers:
        for y in range(h):
            if grid[y][c]==0: out[y][c]=color
    return out
'''
